use rusqlite::{params, Connection, OpenFlags, OptionalExtension, TransactionBehavior};
use serde::{Deserialize, Serialize};
use std::fs::{self, OpenOptions};
use std::io::Write;
use std::os::unix::fs::MetadataExt;
use std::path::{Component, Path, PathBuf};
use std::sync::Mutex;
use std::time::{SystemTime, UNIX_EPOCH};
use tauri::{LogicalSize, Manager};

const DB_NAME: &str = "capture.sqlite";
const BUILD_RUNTIME_ROOT: Option<&str> = option_env!("LIFEOS_RUNTIME_ROOT");
const IPC_ALLOWLIST: [&str; 8] = ["capture_record", "get_today", "runtime_status", "confirm_capture_context", "get_context_recovery", "get_context_next_action", "decide_context_next_action", "record_action_result"];
const PERSON_ID: &str = "person:synthetic-owner";
const PROJECT_ID: &str = "synthetic-lifeos-product";
const CONTEXT_ID: &str = "ctx:project:synthetic-lifeos-product";
const SOURCE_ID: &str = "SRC-SYN-WORK-001";
const ARTIFACT_VERSION: &str = "ART-SYN-CONTEXT-RECOVERY-001@v1";
const SUFFICIENT_TEXT: &str = "整理 LifeOS Context Recovery 合成验收记录。";
const SUFFICIENT_KEY: &str = "p3-130-capture-001";
const INSUFFICIENT_TEXT: &str = "LifeOS Context Recovery 合成记录。";
const INSUFFICIENT_KEY: &str = "p3-131-insufficient-001";
const EDITED_TEXT: &str = "整理并复核 LifeOS Context Recovery 合成验收记录。";
const RESULT_TEXT: &str = "已完成合成验收记录整理与复核。";
const RULE_ID: &str = "local_rule:p3-131-v1";

// This remains a Project-backed projection.  There is no generic Context, generic
// Action API, Memory body copy, ModelPort, AgentPort, or renderer storage access.
const SCHEMA: &str = r#"
PRAGMA journal_mode = DELETE;
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS captures (
 id TEXT PRIMARY KEY, content TEXT NOT NULL, created_at_ms INTEGER NOT NULL,
 source TEXT NOT NULL CHECK(source='local_capture'), source_id TEXT NOT NULL,
 artifact_version TEXT NOT NULL, idem_key TEXT NOT NULL UNIQUE
);
CREATE TABLE IF NOT EXISTS projects (
 id TEXT PRIMARY KEY, person_id TEXT NOT NULL, title TEXT NOT NULL, source_id TEXT NOT NULL,
 artifact_version TEXT NOT NULL, source_available INTEGER NOT NULL, generation_current INTEGER NOT NULL,
 tombstoned INTEGER NOT NULL, authorized INTEGER NOT NULL, evidence_ready INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS capture_project_links (
 capture_id TEXT PRIMARY KEY, project_id TEXT NOT NULL, context_id TEXT NOT NULL,
 link_status TEXT NOT NULL CHECK(link_status IN ('candidate','confirmed','rejected')),
 source_id TEXT NOT NULL, artifact_version TEXT NOT NULL,
 FOREIGN KEY(capture_id) REFERENCES captures(id), FOREIGN KEY(project_id) REFERENCES projects(id)
);
CREATE TABLE IF NOT EXISTS derivations (
 id TEXT PRIMARY KEY, context_id TEXT NOT NULL, capture_id TEXT NOT NULL, processor TEXT NOT NULL,
 processor_version TEXT NOT NULL, basis_refs TEXT NOT NULL, why_text TEXT NOT NULL, created_at_ms INTEGER NOT NULL,
 FOREIGN KEY(capture_id) REFERENCES captures(id)
);
CREATE TABLE IF NOT EXISTS candidate_actions (
 id TEXT PRIMARY KEY, context_id TEXT NOT NULL, capture_id TEXT NOT NULL, derivation_id TEXT NOT NULL,
 candidate_text TEXT NOT NULL, candidate_state TEXT NOT NULL CHECK(candidate_state IN ('active','accepted','rejected','deferred')),
 created_at_ms INTEGER NOT NULL, FOREIGN KEY(derivation_id) REFERENCES derivations(id)
);
CREATE TABLE IF NOT EXISTS feedback (
 id INTEGER PRIMARY KEY AUTOINCREMENT, target_kind TEXT NOT NULL CHECK(target_kind IN ('capture_context','candidate_action')),
 target_id TEXT NOT NULL, context_id TEXT NOT NULL, decision TEXT NOT NULL,
 idem_key TEXT NOT NULL UNIQUE, detail TEXT NOT NULL, created_at_ms INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS actions (
 id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL UNIQUE, context_id TEXT NOT NULL,
 action_text TEXT NOT NULL, confirmation_kind TEXT NOT NULL CHECK(confirmation_kind IN ('accept','edit_accept')),
 action_state TEXT NOT NULL CHECK(action_state IN ('open','completed')), created_at_ms INTEGER NOT NULL,
 FOREIGN KEY(candidate_id) REFERENCES candidate_actions(id)
);
CREATE TABLE IF NOT EXISTS action_results (
 id TEXT PRIMARY KEY, action_id TEXT NOT NULL UNIQUE, result_kind TEXT NOT NULL CHECK(result_kind='completed'),
 result_text TEXT NOT NULL, idem_key TEXT NOT NULL UNIQUE, created_at_ms INTEGER NOT NULL,
 FOREIGN KEY(action_id) REFERENCES actions(id)
);
CREATE TABLE IF NOT EXISTS audit (
 id INTEGER PRIMARY KEY AUTOINCREMENT, event TEXT NOT NULL, target_id TEXT NOT NULL,
 created_at_ms INTEGER NOT NULL, detail TEXT NOT NULL
);
PRAGMA user_version = 131;
"#;

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct CaptureRequest { text: String, key: String }
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct EmptyRequest {}
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct ConfirmRequest { capture_id: String, context_id: String, decision: LinkDecision, idempotency_key: String }
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct ContextRequest { context_id: String }
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct NextDecisionRequest { candidate_id: String, decision: NextDecision, edited_text: Option<String>, idempotency_key: String }
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct ActionResultRequest { action_id: String, result: ActionResultKind, result_text: String, idempotency_key: String }
#[derive(Debug, Deserialize, Serialize, Clone, Copy, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
enum LinkDecision { Confirm, Reject }
impl LinkDecision { fn as_str(self) -> &'static str { match self { Self::Confirm => "confirm", Self::Reject => "reject" } } }
#[derive(Debug, Deserialize, Serialize, Clone, Copy, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
enum NextDecision { Accept, EditAccept, Reject, Defer }
impl NextDecision { fn as_str(self) -> &'static str { match self { Self::Accept => "accept", Self::EditAccept => "edit_accept", Self::Reject => "reject", Self::Defer => "defer" } } }
#[derive(Debug, Deserialize, Serialize, Clone, Copy, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
enum ActionResultKind { Completed }
impl ActionResultKind { fn as_str(self) -> &'static str { "completed" } }

#[derive(Debug, Serialize, Clone)]
struct RecordView { id: String, content: String, created_at_ms: u64, source: String, source_id: String, artifact_version: String, identity: &'static str }
#[derive(Debug, Serialize, Clone)]
struct ContextRecovery { context_id: String, project_id: String, person_id: String, project_title: String, state: String, reliable_suggestion: bool, evidence_gap: Option<String>, source_ref: String, artifact_ref: String, typed_link_ref: Option<String>, feedback_ref: Option<String>, audit_ref: Option<String>, memory_copy_created: bool }
#[derive(Debug, Serialize, Clone)]
struct CandidateView { candidate_id: String, text: String, identity: &'static str, derivation_id: String, processor: &'static str, processor_version: &'static str, basis_refs: Vec<String>, evidence_state: &'static str, why: String }
#[derive(Debug, Serialize, Clone)]
struct NextActionResponse { status: String, context_id: String, candidates: Vec<CandidateView>, disclosure: Option<String>, evidence_gap: Option<String> }
#[derive(Debug, Serialize, Clone)]
struct ActionView { action_id: String, text: String, state: String, confirmation_kind: String, candidate_ref: String }
#[derive(Debug, Serialize, Clone)]
struct MemoryProvenance { derivation_refs: Vec<String>, candidate_refs: Vec<String>, feedback_refs: Vec<String>, action_refs: Vec<String>, result_refs: Vec<String>, original_copy_created: bool }
#[derive(Debug, Serialize)]
struct AuditSummary { event_count: usize, capture_saved: usize, capture_repeat: usize, context_feedback: usize, candidate_feedback: usize, action_created: usize, result_recorded: usize }
#[derive(Debug, Serialize)]
struct CaptureResponse { status: String, record: RecordView, record_count: usize, audit_event_count: usize, context_id: String, link_status: String }
#[derive(Debug, Serialize)]
struct ConfirmResponse { status: String, capture_id: String, context_id: String, decision: String, feedback_count: usize, audit_event_count: usize, recovery: ContextRecovery }
#[derive(Debug, Serialize)]
struct DecisionResponse { status: String, candidate_id: String, decision: String, action: Option<ActionView>, feedback_ref: String, audit_event_count: usize }
#[derive(Debug, Serialize)]
struct ResultResponse { status: String, action_id: String, result: String, result_ref: String, audit_event_count: usize }
#[derive(Debug, Serialize)]
struct TodayResponse { status: &'static str, records: Vec<RecordView>, source: &'static str, ai_status: &'static str, audit: AuditSummary, context_recovery: ContextRecovery, confirmed_actions: Vec<ActionView>, todays_focus: Option<String>, memory_provenance: MemoryProvenance }
#[derive(Debug, Serialize)]
struct RuntimeStatusResponse { status: &'static str, offline: bool, ai_enabled: bool, renderer_direct_capabilities: Vec<&'static str>, ipc_allowlist: Vec<&'static str>, unknown_ipc: &'static str, filesystem: bool, raw_database: bool, generic_path_api: bool, shell: bool, process_spawn: bool, network: bool, vault: bool, export: bool, sync: bool, context_recovery: &'static str, candidate_rule: &'static str, memory_duplicate_original: bool }
#[derive(Debug, Serialize)]
struct IpcError { status: &'static str, code: &'static str, message: &'static str }
impl IpcError { fn blocked(code: &'static str, message: &'static str) -> Self { eprintln!("ipc_result status=blocked code={code}"); Self { status:"blocked", code, message } } }

#[derive(Clone)]
struct RuntimePaths { root: PathBuf, db_path: PathBuf, viewport_request: PathBuf }
struct AppState { runtime: RuntimePaths, serial: Mutex<()> }
#[derive(Clone, Copy, PartialEq)]
enum Fault { None, BeforeCommit }

fn now_ms() -> Result<u64,IpcError> { SystemTime::now().duration_since(UNIX_EPOCH).map(|x|x.as_millis() as u64).map_err(|_|IpcError::blocked("clock_unavailable","本地时间不可用；未写入。")) }
fn sqlite_error(_:rusqlite::Error)->IpcError { IpcError::blocked("database_unavailable","本地合成数据库无法验证；未显示成功。") }
fn io_error(_:std::io::Error)->IpcError { IpcError::blocked("path_boundary_unavailable","本地路径边界无法验证；未显示成功。") }
fn optional_metadata(path:&Path)->Result<Option<fs::Metadata>,IpcError> { match fs::symlink_metadata(path) { Ok(x)=>Ok(Some(x)),Err(e) if e.kind()==std::io::ErrorKind::NotFound=>Ok(None),Err(e)=>Err(io_error(e)) } }
fn real_dir(path:&Path)->Result<(),IpcError> { let m=fs::symlink_metadata(path).map_err(io_error)?; if !m.file_type().is_dir()||m.file_type().is_symlink(){return Err(IpcError::blocked("path_symlink_rejected","Runtime 根祖先必须是无链接真实目录。"));} Ok(()) }
fn real_chain(path:&Path)->Result<(),IpcError> { let mut current=PathBuf::new(); for part in path.components(){match part{Component::RootDir=>current.push("/"),Component::Normal(x)=>{current.push(x);real_dir(&current)?},Component::CurDir|Component::ParentDir|Component::Prefix(_)=>return Err(IpcError::blocked("runtime_root_noncanonical","Runtime 根不规范。"))}} Ok(()) }
fn configured_runtime_paths()->Result<RuntimePaths,IpcError>{let raw=BUILD_RUNTIME_ROOT.ok_or_else(||IpcError::blocked("runtime_root_missing","构建时 Runtime 根缺失。"))?;let root=PathBuf::from(raw);if raw.is_empty()||!root.is_absolute()||root.components().any(|x|matches!(x,Component::CurDir|Component::ParentDir|Component::Prefix(_))){return Err(IpcError::blocked("runtime_root_noncanonical","构建时 Runtime 根必须是绝对规范路径。"));}real_chain(&root)?;if fs::canonicalize(&root).map_err(io_error)?!=root{return Err(IpcError::blocked("runtime_root_noncanonical","Runtime 根解析后发生变化。"));}Ok(RuntimePaths{root:root.clone(),db_path:root.join(DB_NAME),viewport_request:root.join("viewport-request.txt")})}
fn regular_or_absent(path:&Path,code:&'static str)->Result<(),IpcError>{if let Some(m)=optional_metadata(path)?{if !m.file_type().is_file()||m.file_type().is_symlink()||m.nlink()!=1{return Err(IpcError::blocked(code,"运行时工件不是普通单链接文件。"));}}Ok(())}
fn db_object(path:&Path)->Result<bool,IpcError>{let Some(m)=optional_metadata(path)?else{return Ok(false)};if !m.file_type().is_file()||m.file_type().is_symlink()||m.nlink()!=1{return Err(IpcError::blocked("database_type_rejected","数据库不是普通单链接文件。"));}Ok(true)}
fn geometry_path(paths:&RuntimePaths,request:&str)->Result<PathBuf,IpcError>{match request{"1280x1024"|"1160x768"|"700x760"=>Ok(paths.root.join(format!("native-geometry-{request}.jsonl"))),_=>Err(IpcError::blocked("viewport_request_rejected","逻辑视口请求不在冻结集合。"))}}
fn validate_db_path(paths:&RuntimePaths)->Result<bool,IpcError>{real_chain(&paths.root)?;regular_or_absent(&paths.viewport_request,"viewport_type_rejected")?;for request in ["1280x1024","1160x768","700x760"]{regular_or_absent(&geometry_path(paths,request)?,"geometry_type_rejected")?;}for suffix in ["-journal","-wal","-shm"]{if optional_metadata(&PathBuf::from(format!("{}{}",paths.db_path.display(),suffix)))?.is_some(){return Err(IpcError::blocked("database_sidecar_rejected","数据库 sidecar 不受支持。"));}}for entry in fs::read_dir(&paths.root).map_err(io_error)?{let name=entry.map_err(io_error)?.file_name().to_string_lossy().into_owned();if name.starts_with(".capture.sqlite.")&&name.ends_with(".shadow"){return Err(IpcError::blocked("candidate_residue_rejected","存在未完成候选数据库。"));}}db_object(&paths.db_path)}
fn initialise(conn:&Connection)->Result<(),IpcError>{conn.execute_batch(SCHEMA).map_err(sqlite_error)?;conn.execute("INSERT OR IGNORE INTO projects(id,person_id,title,source_id,artifact_version,source_available,generation_current,tombstoned,authorized,evidence_ready) VALUES(?1,?2,'LifeOS 产品开发',?3,?4,1,1,0,1,1)",params![PROJECT_ID,PERSON_ID,SOURCE_ID,ARTIFACT_VERSION]).map_err(sqlite_error)?;validate_connection(conn)}
fn validate_connection(conn:&Connection)->Result<(),IpcError>{let quick:String=conn.query_row("PRAGMA quick_check",[],|r|r.get(0)).map_err(sqlite_error)?;let version:i64=conn.query_row("PRAGMA user_version",[],|r|r.get(0)).map_err(sqlite_error)?;if quick!="ok"||version!=131{return Err(IpcError::blocked("database_contract_rejected","数据库完整性或版本不符合 P3-131 合同。"));}let known:i64=conn.query_row("SELECT count(*) FROM sqlite_master WHERE type='table' AND name IN ('captures','projects','capture_project_links','derivations','candidate_actions','feedback','actions','action_results','audit')",[],|r|r.get(0)).map_err(sqlite_error)?;let unexpected:i64=conn.query_row("SELECT count(*) FROM sqlite_master WHERE type='table' AND name NOT IN ('captures','projects','capture_project_links','derivations','candidate_actions','feedback','actions','action_results','audit','sqlite_sequence')",[],|r|r.get(0)).map_err(sqlite_error)?;if known!=9||unexpected!=0{return Err(IpcError::blocked("database_schema_rejected","数据库表结构不符合本任务限定投影。"));}let project:Option<(String,String,String,String)>=conn.query_row("SELECT person_id,source_id,artifact_version,title FROM projects WHERE id=?1",params![PROJECT_ID],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?))).optional().map_err(sqlite_error)?;match project{Some((p,s,a,t))if p==PERSON_ID&&s==SOURCE_ID&&a==ARTIFACT_VERSION&&t=="LifeOS 产品开发"=>Ok(()),_=>Err(IpcError::blocked("project_contract_rejected","Project 身份或来源版本不可信。"))}}
fn open_read(path:&Path)->Result<Connection,IpcError>{let conn=Connection::open_with_flags(path,OpenFlags::SQLITE_OPEN_READ_ONLY).map_err(sqlite_error)?;conn.pragma_update(None,"query_only",true).map_err(sqlite_error)?;validate_connection(&conn)?;Ok(conn)}
fn project_gap(conn:&Connection)->Result<Option<String>,IpcError>{let f:(i64,i64,i64,i64,i64)=conn.query_row("SELECT source_available,generation_current,tombstoned,authorized,evidence_ready FROM projects WHERE id=?1",params![PROJECT_ID],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?,r.get(4)?))).map_err(sqlite_error)?;Ok(if f.0!=1{Some("source_unavailable".into())}else if f.1!=1{Some("generation_stale".into())}else if f.2!=0{Some("project_tombstoned".into())}else if f.3!=1{Some("authorization_missing".into())}else if f.4!=1{Some("evidence_incomplete".into())}else{None})}
fn valid_capture(text:&str,key:&str)->bool{(text==SUFFICIENT_TEXT&&key==SUFFICIENT_KEY)||(text==INSUFFICIENT_TEXT&&key==INSUFFICIENT_KEY)}
fn record_view(id:String,text:String,created:i64,source:String,source_id:String,artifact:String)->Result<RecordView,IpcError>{if !id.starts_with("capture:p3-131:")||!valid_capture(&text,if text==SUFFICIENT_TEXT{SUFFICIENT_KEY}else{INSUFFICIENT_KEY})||created<=0||source!="local_capture"||source_id!=SOURCE_ID||artifact!=ARTIFACT_VERSION{return Err(IpcError::blocked("record_identity_rejected","capture 身份、来源或固定原文不可信。"));}Ok(RecordView{id,content:text,created_at_ms:created as u64,source,source_id,artifact_version:artifact,identity:"user_original"})}
fn records(conn:&Connection)->Result<Vec<RecordView>,IpcError>{let mut stmt=conn.prepare("SELECT id,content,created_at_ms,source,source_id,artifact_version FROM captures ORDER BY created_at_ms,id").map_err(sqlite_error)?;let rows=stmt.query_map([],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?,r.get(4)?,r.get(5)?))).map_err(sqlite_error)?;let mut out=Vec::new();for row in rows{let (id,text,created,source,source_id,artifact)=row.map_err(sqlite_error)?;out.push(record_view(id,text,created,source,source_id,artifact)?);}if out.len()>2{return Err(IpcError::blocked("record_limit_rejected","仅允许两条固定合成 capture。"));}Ok(out)}
fn audit_summary(conn:&Connection)->Result<AuditSummary,IpcError>{let mut stmt=conn.prepare("SELECT event,target_id FROM audit ORDER BY id").map_err(sqlite_error)?;let rows=stmt.query_map([],|r|Ok((r.get::<_,String>(0)?,r.get::<_,String>(1)?))).map_err(sqlite_error)?;let(mut saved,mut repeat,mut context,mut candidate,mut action,mut result)=(0,0,0,0,0,0);for row in rows{let(event,target)=row.map_err(sqlite_error)?;if target.is_empty(){return Err(IpcError::blocked("audit_contract_rejected","审计 target 为空。"));}match event.as_str(){"capture_saved"=>saved+=1,"capture_repeat"=>repeat+=1,"context_confirmed"|"context_rejected"=>context+=1,"candidate_accepted"|"candidate_edit_accepted"|"candidate_rejected"|"candidate_deferred"=>candidate+=1,"action_created"=>action+=1,"action_completed"=>result+=1,_=>return Err(IpcError::blocked("audit_contract_rejected","审计事件不在合同内。"))}}Ok(AuditSummary{event_count:saved+repeat+context+candidate+action+result,capture_saved:saved,capture_repeat:repeat,context_feedback:context,candidate_feedback:candidate,action_created:action,result_recorded:result})}
fn recovery(conn:&Connection,context:&str)->Result<ContextRecovery,IpcError>{if context!=CONTEXT_ID{return Err(IpcError::blocked("context_schema_rejected","只接受冻结的 Project-backed Context ID。"));}let gap=project_gap(conn)?;let link:Option<(String,String)>=conn.query_row("SELECT capture_id,link_status FROM capture_project_links WHERE context_id=?1 ORDER BY capture_id DESC LIMIT 1",params![CONTEXT_ID],|r|Ok((r.get(0)?,r.get(1)?))).optional().map_err(sqlite_error)?;let feedback:Option<i64>=conn.query_row("SELECT id FROM feedback WHERE context_id=?1 ORDER BY id DESC LIMIT 1",params![CONTEXT_ID],|r|r.get(0)).optional().map_err(sqlite_error)?;let state=if let Some(g)=&gap{format!("evidence_gap:{g}")}else if let Some((_,s))=&link{s.clone()}else{"empty".into()};Ok(ContextRecovery{context_id:CONTEXT_ID.into(),project_id:PROJECT_ID.into(),person_id:PERSON_ID.into(),project_title:"LifeOS 产品开发".into(),state,reliable_suggestion:false,evidence_gap:gap,source_ref:SOURCE_ID.into(),artifact_ref:ARTIFACT_VERSION.into(),typed_link_ref:link.as_ref().map(|(c,s)|format!("capture_project_links:{c}:{s}")),feedback_ref:feedback.map(|id|format!("feedback:{id}")),audit_ref:link.map(|(c,_)|format!("audit:capture:{c}")),memory_copy_created:false})}
fn remove_candidate(path:&Path){for x in [path.to_path_buf(),PathBuf::from(format!("{}-journal",path.display())),PathBuf::from(format!("{}-wal",path.display())),PathBuf::from(format!("{}-shm",path.display()))]{let _=fs::remove_file(x);}}
fn candidate_db(paths:&RuntimePaths)->Result<(PathBuf,bool),IpcError>{let present=validate_db_path(paths)?;let candidate=paths.root.join(format!(".capture.sqlite.{}.{}.shadow",now_ms()?,std::process::id()));remove_candidate(&candidate);OpenOptions::new().write(true).create_new(true).open(&candidate).map_err(io_error)?;if present{if let Err(e)=fs::copy(&paths.db_path,&candidate){remove_candidate(&candidate);return Err(io_error(e));}}Ok((candidate,present))}
fn open_candidate(path:&Path,present:bool)->Result<Connection,IpcError>{let conn=Connection::open(path).map_err(sqlite_error)?;conn.execute_batch("PRAGMA foreign_keys=ON; PRAGMA journal_mode=DELETE;").map_err(sqlite_error)?;if present{validate_connection(&conn)?;}else{initialise(&conn)?;}Ok(conn)}
fn publish(paths:&RuntimePaths,candidate:&Path,present:bool)->Result<(),IpcError>{if db_object(&paths.db_path)?!=present{remove_candidate(candidate);return Err(IpcError::blocked("database_object_changed","数据库最终对象在发布前变化。"));}fs::rename(candidate,&paths.db_path).map_err(io_error)?;remove_candidate(candidate);Ok(())}
fn atomic<T,F>(paths:&RuntimePaths,operation:F)->Result<T,IpcError> where F:FnOnce(&mut Connection)->Result<T,IpcError>{let(candidate,present)=candidate_db(paths)?;let outcome=(||{let mut conn=open_candidate(&candidate,present)?;let value=operation(&mut conn)?;validate_connection(&conn)?;Ok(value)})();match outcome{Ok(value)=>{publish(paths,&candidate,present)?;Ok(value)},Err(err)=>{remove_candidate(&candidate);Err(err)}}}
fn capture_impl(paths:&RuntimePaths,request:&CaptureRequest,fault:Fault)->Result<CaptureResponse,IpcError>{if !valid_capture(&request.text,&request.key){return Err(IpcError::blocked("argument_schema_rejected","只接受两条冻结合成原文及其 capture key。"));}let text=request.text.clone();let key=request.key.clone();atomic(paths,move|conn|{let tx=conn.transaction_with_behavior(TransactionBehavior::Immediate).map_err(sqlite_error)?;let prior:Option<(String,String,i64)>=tx.query_row("SELECT id,content,created_at_ms FROM captures WHERE idem_key=?1",params![key],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).optional().map_err(sqlite_error)?;let(status,record,link_status)=if let Some((id,content,created))=prior{if content!=text{return Err(IpcError::blocked("idempotency_conflict","capture key 已绑定不同原文。"));}tx.execute("INSERT INTO audit(event,target_id,created_at_ms,detail) VALUES('capture_repeat',?1,?2,'same_idempotency_key')",params![id,now_ms()? as i64]).map_err(sqlite_error)?;let link:Option<String>=tx.query_row("SELECT link_status FROM capture_project_links WHERE capture_id=?1",params![id],|r|r.get(0)).optional().map_err(sqlite_error)?;(String::from("idempotent_repeat"),record_view(id,content,created,"local_capture".into(),SOURCE_ID.into(),ARTIFACT_VERSION.into())?,link.unwrap_or_else(||"unlinked_insufficient".into()))}else{let now=now_ms()?;let id=format!("capture:p3-131:{now:016x}");tx.execute("INSERT INTO captures(id,content,created_at_ms,source,source_id,artifact_version,idem_key) VALUES(?1,?2,?3,'local_capture',?4,?5,?6)",params![id,text,now as i64,SOURCE_ID,ARTIFACT_VERSION,key]).map_err(sqlite_error)?;let mut link="unlinked_insufficient".to_string();if text==SUFFICIENT_TEXT{tx.execute("INSERT INTO capture_project_links(capture_id,project_id,context_id,link_status,source_id,artifact_version) VALUES(?1,?2,?3,'candidate',?4,?5)",params![id,PROJECT_ID,CONTEXT_ID,SOURCE_ID,ARTIFACT_VERSION]).map_err(sqlite_error)?;link="candidate".into();}tx.execute("INSERT INTO audit(event,target_id,created_at_ms,detail) VALUES('capture_saved',?1,?2,'local_capture')",params![id,now as i64]).map_err(sqlite_error)?;(String::from("saved"),record_view(id,text,now as i64,"local_capture".into(),SOURCE_ID.into(),ARTIFACT_VERSION.into())?,link)};if fault==Fault::BeforeCommit{return Err(IpcError::blocked("injected_atomic_failure","受控失败已注入；未提交。"));}tx.commit().map_err(sqlite_error)?;let count: i64=conn.query_row("SELECT count(*) FROM captures",[],|r|r.get(0)).map_err(sqlite_error)?;let audit=audit_summary(conn)?;Ok(CaptureResponse{status,record,record_count:count as usize,audit_event_count:audit.event_count,context_id:CONTEXT_ID.into(),link_status})})}
fn confirm_impl(paths:&RuntimePaths,request:&ConfirmRequest)->Result<ConfirmResponse,IpcError>{if request.context_id!=CONTEXT_ID||!request.capture_id.starts_with("capture:p3-131:")||!request.idempotency_key.starts_with("p3-131-"){return Err(IpcError::blocked("argument_schema_rejected","Context confirmation 参数不符合任务限定。"));}let req=request.clone();atomic(paths,move|conn|{if project_gap(conn)?.is_some(){return Err(IpcError::blocked("context_evidence_gap","Project Evidence 不可用；未写入确认。"));}let tx=conn.transaction_with_behavior(TransactionBehavior::Immediate).map_err(sqlite_error)?;let existing:Option<(String,String,String)>=tx.query_row("SELECT target_id,context_id,decision FROM feedback WHERE idem_key=?1",params![req.idempotency_key],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).optional().map_err(sqlite_error)?;let(status,decision)=if let Some((target,context,decision))=existing{if target!=req.capture_id||context!=CONTEXT_ID||decision!=req.decision.as_str(){return Err(IpcError::blocked("idempotency_conflict","确认幂等键已绑定不同结果。"));}("idempotent_repeat".to_string(),decision)}else{let link:Option<String>=tx.query_row("SELECT link_status FROM capture_project_links WHERE capture_id=?1 AND context_id=?2",params![req.capture_id,CONTEXT_ID],|r|r.get(0)).optional().map_err(sqlite_error)?;if link.as_deref()!=Some("candidate"){return Err(IpcError::blocked("confirmation_state_rejected","只能决定存在的 capture-Project candidate link。"));}let now=now_ms()?;let status=if req.decision==LinkDecision::Confirm{"confirmed"}else{"rejected"};tx.execute("INSERT INTO feedback(target_kind,target_id,context_id,decision,idem_key,detail,created_at_ms) VALUES('capture_context',?1,?2,?3,?4,'explicit_user_decision',?5)",params![req.capture_id,CONTEXT_ID,req.decision.as_str(),req.idempotency_key,now as i64]).map_err(sqlite_error)?;tx.execute("UPDATE capture_project_links SET link_status=?1 WHERE capture_id=?2",params![status,req.capture_id]).map_err(sqlite_error)?;let event=if req.decision==LinkDecision::Confirm{"context_confirmed"}else{"context_rejected"};tx.execute("INSERT INTO audit(event,target_id,created_at_ms,detail) VALUES(?1,?2,?3,?4)",params![event,req.capture_id,now as i64,CONTEXT_ID]).map_err(sqlite_error)?;(String::from("saved"),req.decision.as_str().into())};tx.commit().map_err(sqlite_error)?;let feedback_count:i64=conn.query_row("SELECT count(*) FROM feedback",[],|r|r.get(0)).map_err(sqlite_error)?;let audit=audit_summary(conn)?;Ok(ConfirmResponse{status,capture_id:req.capture_id,context_id:CONTEXT_ID.into(),decision,feedback_count:feedback_count as usize,audit_event_count:audit.event_count,recovery:recovery(conn,CONTEXT_ID)?})})}
impl Clone for ConfirmRequest { fn clone(&self)->Self{Self{capture_id:self.capture_id.clone(),context_id:self.context_id.clone(),decision:self.decision,idempotency_key:self.idempotency_key.clone()}} }
fn latest_capture(conn:&Connection)->Result<Option<(String,String)>,IpcError>{conn.query_row("SELECT id,content FROM captures ORDER BY created_at_ms DESC,id DESC LIMIT 1",[],|r|Ok((r.get(0)?,r.get(1)?))).optional().map_err(sqlite_error)}
fn candidate_from_row(id:String,text:String,derivation:String,basis:String)->CandidateView{CandidateView{candidate_id:id,text,identity:"system_candidate_next_action",derivation_id:derivation,processor:RULE_ID,processor_version:"v1",basis_refs:basis.split('|').map(str::to_string).collect(),evidence_state:"sufficient",why:"固定本地规则仅在已确认 Project link、当前 Source/Artifact 与 Evidence 全部有效时返回。".into()}}
fn zero_next(context:&str,status:&str,disclosure:&str,gap:Option<String>)->NextActionResponse{NextActionResponse{status:status.into(),context_id:context.into(),candidates:Vec::new(),disclosure:Some(disclosure.into()),evidence_gap:gap}}
fn next_impl(paths:&RuntimePaths,request:&ContextRequest)->Result<NextActionResponse,IpcError>{if request.context_id!=CONTEXT_ID{return Err(IpcError::blocked("context_schema_rejected","只接受冻结 Context ID。"));}if !validate_db_path(paths)?{return Ok(zero_next(CONTEXT_ID,"empty","暂时没有足够证据判断。",None));}let conn=open_read(&paths.db_path)?;if let Some(gap)=project_gap(&conn)?{return Ok(zero_next(CONTEXT_ID,"unreliable","暂时没有足够证据判断。",Some(gap)));}let Some((capture_id,content))=latest_capture(&conn)?else{return Ok(zero_next(CONTEXT_ID,"empty","暂时没有足够证据判断。",None));};if content==INSUFFICIENT_TEXT{return Ok(zero_next(CONTEXT_ID,"insufficient_evidence","暂时没有足够证据判断。",None));}let link:Option<String>=conn.query_row("SELECT link_status FROM capture_project_links WHERE capture_id=?1",params![capture_id],|r|r.get(0)).optional().map_err(sqlite_error)?;if link.as_deref()!=Some("confirmed"){return Ok(zero_next(CONTEXT_ID,"awaiting_context_confirmation","请先确认此 capture 是否属于当前 Project Context。",None));}let existing:Option<(String,String,String,String,String)>=conn.query_row("SELECT c.id,c.candidate_text,c.derivation_id,d.basis_refs,c.candidate_state FROM candidate_actions c JOIN derivations d ON d.id=c.derivation_id WHERE c.capture_id=?1 ORDER BY c.created_at_ms DESC LIMIT 1",params![capture_id],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?,r.get(4)?))).optional().map_err(sqlite_error)?;if let Some((id,text,derivation,basis,candidate_state))=existing{if candidate_state=="active"{return Ok(NextActionResponse{status:"available".into(),context_id:CONTEXT_ID.into(),candidates:vec![candidate_from_row(id,text,derivation,basis)],disclosure:None,evidence_gap:None});}return Ok(zero_next(CONTEXT_ID,"already_decided","此候选已完成用户处置。",None));}drop(conn);atomic(paths,move|conn|{if project_gap(conn)?.is_some(){return Ok(zero_next(CONTEXT_ID,"unreliable","暂时没有足够证据判断。",Some("evidence_changed".into())));}let now=now_ms()?;let derivation_id=format!("derivation:p3-131:{now:016x}");let candidate_id=format!("candidate:p3-131:{now:016x}");let basis=format!("capture:{capture_id}|capture_project_links:{capture_id}:confirmed|source:{SOURCE_ID}|artifact:{ARTIFACT_VERSION}");let tx=conn.transaction_with_behavior(TransactionBehavior::Immediate).map_err(sqlite_error)?;tx.execute("INSERT INTO derivations(id,context_id,capture_id,processor,processor_version,basis_refs,why_text,created_at_ms) VALUES(?1,?2,?3,?4,'v1',?5,?6,?7)",params![derivation_id,CONTEXT_ID,capture_id,RULE_ID,basis,"已确认 Project-backed Context 且固定 Evidence 当前有效。",now as i64]).map_err(sqlite_error)?;tx.execute("INSERT INTO candidate_actions(id,context_id,capture_id,derivation_id,candidate_text,candidate_state,created_at_ms) VALUES(?1,?2,?3,?4,?5,'active',?6)",params![candidate_id,CONTEXT_ID,capture_id,derivation_id,SUFFICIENT_TEXT,now as i64]).map_err(sqlite_error)?;tx.commit().map_err(sqlite_error)?;Ok(NextActionResponse{status:"available".into(),context_id:CONTEXT_ID.into(),candidates:vec![candidate_from_row(candidate_id,SUFFICIENT_TEXT.into(),derivation_id,basis)],disclosure:None,evidence_gap:None})})}
fn action_view(conn:&Connection,id:&str)->Result<ActionView,IpcError>{conn.query_row("SELECT id,action_text,action_state,confirmation_kind,candidate_id FROM actions WHERE id=?1",params![id],|r|Ok(ActionView{action_id:r.get(0)?,text:r.get(1)?,state:r.get(2)?,confirmation_kind:r.get(3)?,candidate_ref:r.get(4)?})).map_err(sqlite_error)}
fn decide_impl(paths:&RuntimePaths,request:&NextDecisionRequest)->Result<DecisionResponse,IpcError>{if !request.candidate_id.starts_with("candidate:p3-131:")||!request.idempotency_key.starts_with("p3-131-"){return Err(IpcError::blocked("argument_schema_rejected","Candidate decision 参数不符合任务限定。"));}if request.decision==NextDecision::EditAccept&&request.edited_text.as_deref()!=Some(EDITED_TEXT){return Err(IpcError::blocked("edited_text_rejected","编辑确认必须使用冻结编辑文本。"));}if request.decision!=NextDecision::EditAccept&&request.edited_text.is_some(){return Err(IpcError::blocked("edited_text_rejected","仅 edit_accept 可提供 edited_text。"));}let req=request.clone();atomic(paths,move|conn|{let tx=conn.transaction_with_behavior(TransactionBehavior::Immediate).map_err(sqlite_error)?;let existing:Option<(String,String,String)>=tx.query_row("SELECT target_id,decision,detail FROM feedback WHERE idem_key=?1",params![req.idempotency_key],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).optional().map_err(sqlite_error)?;let(status,decision,action_id,feedback_ref)=if let Some((target,decision,detail))=existing{if target!=req.candidate_id||decision!=req.decision.as_str(){return Err(IpcError::blocked("idempotency_conflict","处置幂等键已绑定不同结果。"));}("idempotent_repeat".into(),decision,detail.clone(),format!("feedback:{detail}"))}else{let state:Option<String>=tx.query_row("SELECT candidate_state FROM candidate_actions WHERE id=?1",params![req.candidate_id],|r|r.get(0)).optional().map_err(sqlite_error)?;if state.as_deref()!=Some("active"){return Err(IpcError::blocked("candidate_state_rejected","只能处置开放的 Candidate Next Action。"));}let now=now_ms()?;let mut action_detail="".to_string();let event=match req.decision{NextDecision::Accept=>"candidate_accepted",NextDecision::EditAccept=>"candidate_edit_accepted",NextDecision::Reject=>"candidate_rejected",NextDecision::Defer=>"candidate_deferred"};if matches!(req.decision,NextDecision::Accept|NextDecision::EditAccept){let action_id=format!("action:p3-131:{now:016x}");let text=if req.decision==NextDecision::EditAccept{EDITED_TEXT}else{SUFFICIENT_TEXT};tx.execute("INSERT INTO actions(id,candidate_id,context_id,action_text,confirmation_kind,action_state,created_at_ms) VALUES(?1,?2,?3,?4,?5,'open',?6)",params![action_id,req.candidate_id,CONTEXT_ID,text,req.decision.as_str(),now as i64]).map_err(sqlite_error)?;tx.execute("INSERT INTO audit(event,target_id,created_at_ms,detail) VALUES('action_created',?1,?2,?3)",params![action_id,now as i64,req.decision.as_str()]).map_err(sqlite_error)?;action_detail=action_id;}tx.execute("INSERT INTO feedback(target_kind,target_id,context_id,decision,idem_key,detail,created_at_ms) VALUES('candidate_action',?1,?2,?3,?4,?5,?6)",params![req.candidate_id,CONTEXT_ID,req.decision.as_str(),req.idempotency_key,action_detail,now as i64]).map_err(sqlite_error)?;let state=match req.decision{NextDecision::Accept|NextDecision::EditAccept=>"accepted",NextDecision::Reject=>"rejected",NextDecision::Defer=>"deferred"};tx.execute("UPDATE candidate_actions SET candidate_state=?1 WHERE id=?2",params![state,req.candidate_id]).map_err(sqlite_error)?;tx.execute("INSERT INTO audit(event,target_id,created_at_ms,detail) VALUES(?1,?2,?3,?4)",params![event,req.candidate_id,now as i64,req.decision.as_str()]).map_err(sqlite_error)?;(String::from("saved"),req.decision.as_str().into(),action_detail.clone(),format!("feedback:{}",now))};tx.commit().map_err(sqlite_error)?;let action=if action_id.is_empty(){None}else{Some(action_view(conn,&action_id)?)};let audit=audit_summary(conn)?;Ok(DecisionResponse{status,candidate_id:req.candidate_id,decision,action,feedback_ref,audit_event_count:audit.event_count})})}
impl Clone for NextDecisionRequest { fn clone(&self)->Self{Self{candidate_id:self.candidate_id.clone(),decision:self.decision,edited_text:self.edited_text.clone(),idempotency_key:self.idempotency_key.clone()}} }
fn result_impl(paths:&RuntimePaths,request:&ActionResultRequest)->Result<ResultResponse,IpcError>{if !request.action_id.starts_with("action:p3-131:")||request.result!=ActionResultKind::Completed||request.result_text!=RESULT_TEXT||!request.idempotency_key.starts_with("p3-131-"){return Err(IpcError::blocked("argument_schema_rejected","Action Result 参数不符合冻结合同。"));}let req=request.clone();atomic(paths,move|conn|{let tx=conn.transaction_with_behavior(TransactionBehavior::Immediate).map_err(sqlite_error)?;let existing:Option<(String,String)>=tx.query_row("SELECT action_id,result_text FROM action_results WHERE idem_key=?1",params![req.idempotency_key],|r|Ok((r.get(0)?,r.get(1)?))).optional().map_err(sqlite_error)?;let(status,result_ref)=if let Some((action,text))=existing{if action!=req.action_id||text!=RESULT_TEXT{return Err(IpcError::blocked("idempotency_conflict","结果幂等键已绑定不同 Action 或文本。"));}("idempotent_repeat".into(),format!("action_result:{action}"))}else{let state:Option<String>=tx.query_row("SELECT action_state FROM actions WHERE id=?1",params![req.action_id],|r|r.get(0)).optional().map_err(sqlite_error)?;if state.as_deref()!=Some("open"){return Err(IpcError::blocked("action_state_rejected","只能为已确认且开放的 Action 记录完成结果。"));}let now=now_ms()?;let id=format!("action_result:p3-131:{now:016x}");tx.execute("INSERT INTO action_results(id,action_id,result_kind,result_text,idem_key,created_at_ms) VALUES(?1,?2,'completed',?3,?4,?5)",params![id,req.action_id,RESULT_TEXT,req.idempotency_key,now as i64]).map_err(sqlite_error)?;tx.execute("UPDATE actions SET action_state='completed' WHERE id=?1",params![req.action_id]).map_err(sqlite_error)?;tx.execute("INSERT INTO audit(event,target_id,created_at_ms,detail) VALUES('action_completed',?1,?2,'completed')",params![req.action_id,now as i64]).map_err(sqlite_error)?;(String::from("saved"),id)};tx.commit().map_err(sqlite_error)?;let audit=audit_summary(conn)?;Ok(ResultResponse{status,action_id:req.action_id,result:req.result.as_str().into(),result_ref,audit_event_count:audit.event_count})})}
impl Clone for ActionResultRequest { fn clone(&self)->Self{Self{action_id:self.action_id.clone(),result:self.result,result_text:self.result_text.clone(),idempotency_key:self.idempotency_key.clone()}} }
fn actions_open(conn:&Connection)->Result<Vec<ActionView>,IpcError>{let mut stmt=conn.prepare("SELECT id,action_text,action_state,confirmation_kind,candidate_id FROM actions WHERE action_state='open' ORDER BY created_at_ms,id").map_err(sqlite_error)?;let rows=stmt.query_map([],|r|Ok(ActionView{action_id:r.get(0)?,text:r.get(1)?,state:r.get(2)?,confirmation_kind:r.get(3)?,candidate_ref:r.get(4)?})).map_err(sqlite_error)?;let mut out=Vec::new();for row in rows{out.push(row.map_err(sqlite_error)?);}Ok(out)}
fn memory_provenance(conn:&Connection)->Result<MemoryProvenance,IpcError>{let collect=|sql:&str|->Result<Vec<String>,IpcError>{let mut s=conn.prepare(sql).map_err(sqlite_error)?;let rows=s.query_map([],|r|r.get(0)).map_err(sqlite_error)?;let mut out=Vec::new();for row in rows{out.push(row.map_err(sqlite_error)?);}Ok(out)};Ok(MemoryProvenance{derivation_refs:collect("SELECT id FROM derivations ORDER BY id")?,candidate_refs:collect("SELECT id FROM candidate_actions ORDER BY id")?,feedback_refs:collect("SELECT 'feedback:' || id FROM feedback ORDER BY id")?,action_refs:collect("SELECT id FROM actions ORDER BY id")?,result_refs:collect("SELECT id FROM action_results ORDER BY id")?,original_copy_created:false})}
fn today_from(conn:&Connection,status:&'static str)->Result<TodayResponse,IpcError>{let actions=actions_open(conn)?;Ok(TodayResponse{status,records:records(conn)?,source:"local_capture",ai_status:"disabled",audit:audit_summary(conn)?,context_recovery:recovery(conn,CONTEXT_ID)?,confirmed_actions:actions,todays_focus:None,memory_provenance:memory_provenance(conn)?})}
fn today_impl(paths:&RuntimePaths)->Result<TodayResponse,IpcError>{if !validate_db_path(paths)?{let conn=Connection::open_in_memory().map_err(sqlite_error)?;initialise(&conn)?;return today_from(&conn,"empty");}let conn=open_read(&paths.db_path)?;today_from(&conn,"loaded")}
fn recovery_impl(paths:&RuntimePaths,request:&ContextRequest)->Result<ContextRecovery,IpcError>{if request.context_id!=CONTEXT_ID{return Err(IpcError::blocked("context_schema_rejected","只接受冻结 Context ID。"));}if !validate_db_path(paths)?{let conn=Connection::open_in_memory().map_err(sqlite_error)?;initialise(&conn)?;return recovery(&conn,CONTEXT_ID);}let conn=open_read(&paths.db_path)?;recovery(&conn,CONTEXT_ID)}
fn status_impl()->RuntimeStatusResponse{RuntimeStatusResponse{status:"restricted_offline",offline:true,ai_enabled:false,renderer_direct_capabilities:Vec::new(),ipc_allowlist:IPC_ALLOWLIST.to_vec(),unknown_ipc:"deny",filesystem:false,raw_database:false,generic_path_api:false,shell:false,process_spawn:false,network:false,vault:false,export:false,sync:false,context_recovery:"project_backed_only",candidate_rule:RULE_ID,memory_duplicate_original:false}}
fn viewport_request(paths:&RuntimePaths)->Result<String,IpcError>{let request=match optional_metadata(&paths.viewport_request)?{Some(_)=>fs::read_to_string(&paths.viewport_request).map_err(io_error)?.trim().to_string(),None=>"1280x1024".into()};geometry_path(paths,&request)?;Ok(request)}
fn native_geometry(paths:&RuntimePaths,window:&tauri::Window,phase:&str,requested:&str)->Result<(),IpcError>{let path=geometry_path(paths,requested)?;regular_or_absent(&path,"geometry_type_rejected")?;let scale=window.scale_factor().map_err(|_|IpcError::blocked("native_geometry_unavailable","无法读取原生窗口比例。"))?;let inner=window.inner_size().map_err(|_|IpcError::blocked("native_geometry_unavailable","无法读取内容边界。"))?;let outer=window.outer_size().map_err(|_|IpcError::blocked("native_geometry_unavailable","无法读取窗口边界。"))?;let i=inner.to_logical::<f64>(scale);let o=outer.to_logical::<f64>(scale);let line=serde_json::json!({"task":"LIFEOS-P3-131","source":"actual-tauri-native-window","phase":phase,"requested_logical":requested,"scale_factor":scale,"content_bounds":{"size_physical":{"width":inner.width,"height":inner.height},"size_logical":{"width":i.width,"height":i.height}},"outer_bounds":{"size_physical":{"width":outer.width,"height":outer.height},"size_logical":{"width":o.width,"height":o.height}}});let mut f=OpenOptions::new().create(true).append(true).open(path).map_err(io_error)?;writeln!(f,"{line}").map_err(io_error)?;Ok(())}
#[tauri::command] fn capture_record(request:CaptureRequest,state:tauri::State<'_,AppState>)->Result<CaptureResponse,IpcError>{let _g=state.serial.lock().map_err(|_|IpcError::blocked("runtime_lock_unavailable","运行时锁不可用。"))?;capture_impl(&state.runtime,&request,Fault::None)}
#[tauri::command] fn get_today(request:EmptyRequest,state:tauri::State<'_,AppState>)->Result<TodayResponse,IpcError>{let _=request;let _g=state.serial.lock().map_err(|_|IpcError::blocked("runtime_lock_unavailable","运行时锁不可用。"))?;today_impl(&state.runtime)}
#[tauri::command] fn runtime_status(request:EmptyRequest)->RuntimeStatusResponse{let _=request;status_impl()}
#[tauri::command] fn confirm_capture_context(request:ConfirmRequest,state:tauri::State<'_,AppState>)->Result<ConfirmResponse,IpcError>{let _g=state.serial.lock().map_err(|_|IpcError::blocked("runtime_lock_unavailable","运行时锁不可用。"))?;confirm_impl(&state.runtime,&request)}
#[tauri::command] fn get_context_recovery(request:ContextRequest,state:tauri::State<'_,AppState>)->Result<ContextRecovery,IpcError>{let _g=state.serial.lock().map_err(|_|IpcError::blocked("runtime_lock_unavailable","运行时锁不可用。"))?;recovery_impl(&state.runtime,&request)}
#[tauri::command] fn get_context_next_action(request:ContextRequest,state:tauri::State<'_,AppState>)->Result<NextActionResponse,IpcError>{let _g=state.serial.lock().map_err(|_|IpcError::blocked("runtime_lock_unavailable","运行时锁不可用。"))?;next_impl(&state.runtime,&request)}
#[tauri::command] fn decide_context_next_action(request:NextDecisionRequest,state:tauri::State<'_,AppState>)->Result<DecisionResponse,IpcError>{let _g=state.serial.lock().map_err(|_|IpcError::blocked("runtime_lock_unavailable","运行时锁不可用。"))?;decide_impl(&state.runtime,&request)}
#[tauri::command] fn record_action_result(request:ActionResultRequest,state:tauri::State<'_,AppState>)->Result<ResultResponse,IpcError>{let _g=state.serial.lock().map_err(|_|IpcError::blocked("runtime_lock_unavailable","运行时锁不可用。"))?;result_impl(&state.runtime,&request)}
pub fn run(){let runtime=configured_runtime_paths().unwrap_or_else(|e|panic!("P3-131 Runtime root rejected: {}",e.code));validate_db_path(&runtime).unwrap_or_else(|e|panic!("P3-131 database boundary rejected: {}",e.code));let requested=viewport_request(&runtime).unwrap_or_else(|e|panic!("P3-131 viewport rejected: {}",e.code));let setup=runtime.clone();let events=runtime.clone();tauri::Builder::default().manage(AppState{runtime,serial:Mutex::new(())}).setup(move|app|{let(w,h)=match requested.as_str(){"1280x1024"=>(1280.0,1024.0),"1160x768"=>(1160.0,768.0),"700x760"=>(700.0,760.0),_=>panic!("unsupported viewport")};let webview=app.get_webview_window("main").expect("main window missing");let window=webview.as_ref().window();let scale=window.scale_factor().expect("scale");let inner=window.inner_size().expect("inner").to_logical::<f64>(scale);let outer=window.outer_size().expect("outer").to_logical::<f64>(scale);window.set_size(LogicalSize::new(w+(outer.width-inner.width).max(0.0),h+(outer.height-inner.height).max(0.0))).expect("resize");native_geometry(&setup,&window,"setup",&requested).unwrap_or_else(|e|panic!("geometry: {}",e.code));Ok(())}).on_window_event(move|window,event|{if matches!(event,tauri::WindowEvent::Resized(_)){let current=viewport_request(&events).unwrap_or_else(|e|panic!("geometry viewport: {}",e.code));native_geometry(&events,window,"resized",&current).unwrap_or_else(|e|panic!("geometry: {}",e.code));}}).invoke_handler(tauri::generate_handler![capture_record,get_today,runtime_status,confirm_capture_context,get_context_recovery,get_context_next_action,decide_context_next_action,record_action_result]).run(tauri::generate_context!()).expect("P3-131 Tauri runtime failed");}

#[cfg(test)]
mod tests{
 use super::*; use sha2::{Digest,Sha256};
 fn paths(name:&str)->RuntimePaths{let base=configured_runtime_paths().unwrap().root;let root=base.join(format!("unit-{name}-{}",std::process::id()));let _=fs::remove_dir_all(&root);fs::create_dir(&root).unwrap();RuntimePaths{db_path:root.join(DB_NAME),viewport_request:root.join("viewport-request.txt"),root}}
 fn clean(p:&RuntimePaths){assert_eq!(p.root.parent(),Some(configured_runtime_paths().unwrap().root.as_path()));fs::remove_dir_all(&p.root).unwrap()}
 fn hash(p:&Path)->String{let mut d=Sha256::new();d.update(fs::read(p).unwrap());format!("{:x}",d.finalize())}
 fn cap(text:&str,key:&str)->CaptureRequest{CaptureRequest{text:text.into(),key:key.into()}}
 fn confirmed(p:&RuntimePaths)->String{let c=capture_impl(p,&cap(SUFFICIENT_TEXT,SUFFICIENT_KEY),Fault::None).unwrap();confirm_impl(p,&ConfirmRequest{capture_id:c.record.id.clone(),context_id:CONTEXT_ID.into(),decision:LinkDecision::Confirm,idempotency_key:"p3-131-link-001".into()}).unwrap();c.record.id}
 fn candidate(p:&RuntimePaths)->String{confirmed(p);next_impl(p,&ContextRequest{context_id:CONTEXT_ID.into()}).unwrap().candidates[0].candidate_id.clone()}
 #[test] fn direct_accept_complete_and_reopen_are_traceable(){let p=paths("direct");let c=candidate(&p);let d=decide_impl(&p,&NextDecisionRequest{candidate_id:c.clone(),decision:NextDecision::Accept,edited_text:None,idempotency_key:"p3-131-accept-001".into()}).unwrap();let action=d.action.unwrap();assert_eq!(decide_impl(&p,&NextDecisionRequest{candidate_id:c,decision:NextDecision::Defer,edited_text:None,idempotency_key:"p3-131-accept-001".into()}).unwrap_err().code,"idempotency_conflict");assert!(next_impl(&p,&ContextRequest{context_id:CONTEXT_ID.into()}).unwrap().candidates.is_empty());assert_eq!(today_impl(&p).unwrap().confirmed_actions.len(),1);let request=ActionResultRequest{action_id:action.action_id.clone(),result:ActionResultKind::Completed,result_text:RESULT_TEXT.into(),idempotency_key:"p3-131-result-001".into()};let r=result_impl(&p,&request).unwrap();assert_eq!(r.status,"saved");assert_eq!(result_impl(&p,&request).unwrap().status,"idempotent_repeat");let before=hash(&p.db_path);assert_eq!(result_impl(&p,&ActionResultRequest{action_id:action.action_id.clone(),result:ActionResultKind::Completed,result_text:RESULT_TEXT.into(),idempotency_key:"p3-131-result-conflict-001".into()}).unwrap_err().code,"action_state_rejected");assert_eq!(before,hash(&p.db_path));let reopened=today_impl(&p).unwrap();assert!(reopened.confirmed_actions.is_empty());assert_eq!(reopened.memory_provenance.result_refs.len(),1);assert!(!reopened.memory_provenance.original_copy_created);clean(&p)}
 #[test] fn edit_accept_separates_candidate_and_user_action(){let p=paths("edit");let c=candidate(&p);let d=decide_impl(&p,&NextDecisionRequest{candidate_id:c,decision:NextDecision::EditAccept,edited_text:Some(EDITED_TEXT.into()),idempotency_key:"p3-131-edit-001".into()}).unwrap();let a=d.action.unwrap();assert_eq!(a.text,EDITED_TEXT);assert_eq!(a.confirmation_kind,"edit_accept");clean(&p)}
 #[test] fn reject_and_defer_append_feedback_without_action(){for(kind,key)in[(NextDecision::Reject,"p3-131-reject-001"),(NextDecision::Defer,"p3-131-defer-001")]{let p=paths(key);let c=candidate(&p);let d=decide_impl(&p,&NextDecisionRequest{candidate_id:c.clone(),decision:kind,edited_text:None,idempotency_key:key.into()}).unwrap();assert!(d.action.is_none());assert_eq!(decide_impl(&p,&NextDecisionRequest{candidate_id:c,decision:kind,edited_text:None,idempotency_key:key.into()}).unwrap().status,"idempotent_repeat");assert!(today_impl(&p).unwrap().confirmed_actions.is_empty());clean(&p)}}
 #[test] fn insufficient_evidence_has_no_derivation_candidate_action_or_feedback(){let p=paths("insufficient");capture_impl(&p,&cap(INSUFFICIENT_TEXT,INSUFFICIENT_KEY),Fault::None).unwrap();let response=next_impl(&p,&ContextRequest{context_id:CONTEXT_ID.into()}).unwrap();assert!(response.candidates.is_empty());assert_eq!(response.disclosure.as_deref(),Some("暂时没有足够证据判断。"));let conn=open_read(&p.db_path).unwrap();for table in ["derivations","candidate_actions","actions","feedback"]{let n:i64=conn.query_row(&format!("SELECT count(*) FROM {table}"),[],|r|r.get(0)).unwrap();assert_eq!(n,0);}clean(&p)}
 #[test] fn mutations_and_invalid_requests_are_no_write(){for field in ["source_available=0","generation_current=0","tombstoned=1","authorized=0","evidence_ready=0"]{let p=paths(field);confirmed(&p);let conn=Connection::open(&p.db_path).unwrap();conn.execute(&format!("UPDATE projects SET {field} WHERE id=?1"),params![PROJECT_ID]).unwrap();drop(conn);let before=hash(&p.db_path);let response=next_impl(&p,&ContextRequest{context_id:CONTEXT_ID.into()}).unwrap();assert!(response.candidates.is_empty());assert_eq!(before,hash(&p.db_path));clean(&p);}let p=paths("invalid");let c=candidate(&p);let before=hash(&p.db_path);assert_eq!(decide_impl(&p,&NextDecisionRequest{candidate_id:c,decision:NextDecision::EditAccept,edited_text:None,idempotency_key:"p3-131-invalid-001".into()}).unwrap_err().code,"edited_text_rejected");assert_eq!(before,hash(&p.db_path));assert_eq!(decide_impl(&p,&NextDecisionRequest{candidate_id:"candidate:p3-131:not-present".into(),decision:NextDecision::Accept,edited_text:None,idempotency_key:"p3-131-illegal-id-001".into()}).unwrap_err().code,"candidate_state_rejected");assert_eq!(before,hash(&p.db_path));assert!(serde_json::from_str::<NextDecisionRequest>(r#"{"candidate_id":"candidate:p3-131:x","decision":"accept","idempotency_key":"p3-131-x","sql":"select 1"}"#).is_err());println!("P3_131_MUTATION_RESULTS={}",serde_json::json!({"mutations":["source_available","generation_current","tombstoned","authorized","evidence_ready"],"candidate_count":0,"database_hash_unchanged":true,"unknown_field":"rejected","missing_edited_text":"edited_text_rejected","illegal_id":"candidate_state_rejected"}));clean(&p)}
 #[test] fn status_has_exactly_eight_commands(){assert_eq!(status_impl().ipc_allowlist,IPC_ALLOWLIST)}
}
